def gen(rng):
    letters = 'abcdefghijklmnopqrstuvwxyz'
    vowels = 'aeiouAEIOU'

    def word(maxlen, pv):
        w = ''
        for _ in range(rng.randint(1, maxlen)):
            if rng.random() < pv:
                w += rng.choice(vowels)
            else:
                c = rng.choice(letters)
                w += c.upper() if rng.random() < 0.2 else c
        return w

    def sent(maxwords, maxlen, pv):
        return ' '.join(word(maxlen, pv) for _ in range(rng.randint(1, maxwords)))

    tests = ['a', 'b', 'hello world', 'Idea', 'sky', 'AEIOU', 'aeiou aeiou', 'a b', 'rhythm', 'Programming Is Fun']
    for _ in range(40):
        tests.append(sent(6, 8, rng.choice([0.1, 0.4, 0.8])))
    tests.append('a' * 500)
    tests.append('E' * 250 + ' ' + 'o' * 249)
    tests.append(' '.join(word(10, 0.5) for _ in range(60))[:499].rstrip())
    tests.append(('ab cd ' * 100)[:499].rstrip())
    tests.append('x' * 500)
    return tests
